    await dbq('INSERT INTO daily_scores (day, player_id, tries, rounds, hp, at) VALUES ($1, $2, 1, 1, 100, now())', [E.dayKey(Date.now()), prizeIds[10]]);
    check('a day still running pays nothing yet', (await today('/api/daily/me')).body.unclaimed === false && (await today('/api/daily/claim', {})).body.prizes.length === 0);
    const { ticketEnd } = require('../lib/daily');
    check('a battle must end within 15 minutes of its day closing', ticketEnd('2026-12-01', Date.parse('2026-12-01T23:59:00Z')) === Date.parse('2026-12-02T00:15:00Z') && ticketEnd('2026-12-01', Date.parse('2026-12-01T08:00:00Z')) === Date.parse('2026-12-01T09:30:00Z'));
    check('this ticket follows that rule', dt.exp <= Date.parse(ch.day + 'T00:00:00Z') + 864e5 + 15 * 60000, dt.exp);
    check('claiming needs a sign in', (await client()('/api/daily/claim', {})).status === 401);
    await dbq(`INSERT INTO rare_drops (player_id, source, kind, ref) VALUES ($1, 'chest 3', 'pet', 'sandman')`, [id]);
