  for (let i = 0; i < 4000; i++) { const r = E.finishWin(gR, B20, floors); chestN += r.chests.length; if (r.first || r.coins !== Math.round((25 + 160) * .3)) coinsRight = false; }
  check('a replay pays 30% of the normal coins, with no boss bonus', coinsRight);
  check('a replay gives a chest about 70% of the time', chestN / 4000 > .67 && chestN / 4000 < .73, chestN / 4000);
  check('replay chests are one tier lower', gR.chests[2] === 0 && gR.chests[3] === 0 && gR.chests[1] < chestN * .06 && gR.chests[1] > 0, gR.chests);
